import math
S={'ph':'fwd','d':0.0,'rd':0.0,'w':0}
def control(obs):
    try:
        return _c(obs)
    except Exception as ex:
        print('ERR',ex)
        return (0.0,0.0,-23)
def _c(obs):
    h=obs['hitch_deg'];dt=obs.get('dt',0.1);v=obs['motion']['v_mps']
    if S['ph']=='fwd':
        if v>0: S['d']+=v*dt
        if S['d']>=3.5 or (S['d']>=2.5 and abs(h)<4):
            S['ph']='rev';print('rev start h=%.1f d=%.2f'%(h,S['d']))
        else:
            return (0.0,0.8,-23)
    if v<0: S['rd']+=-v*dt
    rig=obs['rig'];R=rig['trailer_rear'];th=rig['trailer_heading_deg']
    B=math.radians(th+180)
    cam=(obs.get('views') or {}).get('camera') or {}
    o=cam.get('origin',R)
    close=9
    for w in cam.get('walls',[]) or []:
        px=o[0]+w[1]*math.cos(math.radians(w[0]))-R[0];py=o[1]+w[1]*math.sin(math.radians(w[0]))-R[1]
        al=px*math.cos(B)+py*math.sin(B);ac=abs(-px*math.sin(B)+py*math.cos(B))
        if al>0 and ac<0.9: close=min(close,al)
    if close<0.2 or S['rd']>4.5:
        if not S['w']:
            S['w']=1;wake('stopped: close=%.2f rd=%.2f h=%.1f'%(close,S['rd'],h))
        return (0.0,0.0,-23)
    st=max(-34,min(34,2.5*h))
    return (st,-0.6,-23)

