import math
mode='fwd'
dist=0.0
last_t=None
seq=[170,130,100,64,30,0,-30,-64,-100,-130,-170]
li=0
lt=None
pts={}
done=False

def control(obs):
    global mode,dist,last_t,li,lt,done
    t=obs['t']; v=obs['motion']['v_mps']
    if last_t is not None:
        d=t-last_t
        if 0<d<1: dist+=abs(v)*d
    last_t=t
    if mode=='fwd':
        if dist>2.5:
            mode='stop'
        else:
            return (0.0,0.6,64)
    if mode=='stop':
        if abs(v)<0.01:
            mode='scan'; lt=t
        return (0.0,0.0,seq[0])
    if mode=='scan':
        h=obs['head']
        if h.get('settled') and abs(h['gaze_deg']-seq[li])<2:
            for name,vw in (obs.get('views') or {}).items():
                if not vw: continue
                o=vw.get('origin',[0,0])
                for p in vw.get('walls',[]) or []:
                    if p[1]>22: continue
                    br=math.radians(p[0])
                    x=o[0]+p[1]*math.cos(br); y=o[1]+p[1]*math.sin(br)
                    pts[(round(x*2)/2.0,round(y*2)/2.0)]=1
            if t-lt>0.9:
                li+=1; lt=t
        else:
            lt=t if lt is None else lt
        if li>=len(seq):
            mode='end'
            ks=sorted(pts.keys())
            print('phi %.1f pts:'%obs['hitch_deg']+' '.join('%g,%g'%k for k in ks))
            print('tgt',obs.get('target'),'rig',obs['rig']['trailer_rear'])
            wake('scan done')
            return (0.0,0.0,0)
        return (0.0,0.0,seq[li])
    return (0.0,0.0,0)

