X=-0.75; Y=0.0; TH=0.03
last_t=None
P=[]
d0=(-0.9397,0.3420)
for i in range(int(13.87/0.25)+1):
    tt=-6+i*0.25
    P.append((d0[0]*tt,0.1+d0[1]*tt))
cx=-5.001; cy=9.370
N=34
for k in range(1,N+1):
    a=math.radians(-110-70.0*k/N)
    P.append((cx+7*math.cos(a),cy+7*math.sin(a)))
y0=9.37
while y0<22:
    y0+=0.25
    P.append((-12.0,y0))
INIT='-10,9 -9.5,9 -9,9 -9,10 -9.5,11 -10,12 -10,14 -10,16 -8.5,7.5 -8.5,8.5 -8,7 -7.5,6.5 -7,6 -6.5,6 -6,5.5 -5.5,5 -5,4.5 -4.5,4.5 -4,4.5 -3.5,4 -3,4 -2.5,3.5 -2,3.5 -1.5,3.5 -1,3 -0.5,3 0,2.5 0.5,2.5 1,2 1.5,2.5 2,2 2.5,2 3,2 3.5,1.5 4,1.5 4.5,1.5 5,1.5 5.5,1 6,1 6.5,0.5 7,0 7.5,0 8,0 8.5,0 9,-0.5 9.5,-1 10,-1.5 -4,-1 -3.5,-1.5 -3,-2 -2.5,-2 -2,-2 -1.5,-2 -1,-2 -0.5,-2.5 0,-2.5 0.5,-2.5 1,-3 1.5,-3 2,-3 2.5,-3.5 3,-3.5 3.5,-3.5 4,-4 4.5,-4 5,-4 5.5,-4.5 6,-4.5 6.5,-5 7,-5 7.5,-5 8,-5.5 8.5,-5.5 9,-5'
mp={}
for s in INIT.split():
    a,b=s.split(',')
    mp[(int(round(float(a)/G)),int(round(float(b)/G)))]=1e9
idx=30
mode='rev'
seq=[150,64,-30,-64,-150,30]
li=0; look_t=0.0
lastp=-10.0; lastprune=0.0
woken=False
sseq=[170,130,100,64,30,0,-30,-64,-100,-130,-170]
sli=0; slt=None; spts={}

def clip(a,lo,hi):
    return max(lo,min(hi,a))

def wrap(a):
    while a>math.pi: a-=2*math.pi
    while a<-math.pi: a+=2*math.pi
    return a

def control(obs):
    global X,Y,TH,last_t,idx,mode,li,look_t,lastp,lastprune,woken,sli,slt
    t=obs['t']; v=obs['motion']['v_mps']
    st=math.radians(obs['steer_deg'])
    if last_t is not None:
        d=t-last_t
        if 0<d<1:
            X+=v*math.cos(TH)*d; Y+=v*math.sin(TH)*d; TH+=v*math.tan(st)/L*d
    last_t=t
    c=math.cos(TH); s=math.sin(TH)
    views=obs.get('views') or {}
    for name,vw in views.items():
        if not vw: continue
        o=vw.get('origin',[0,0])
        for p in vw.get('walls',[]) or []:
            if p[1]>14: continue
            br=math.radians(p[0])
            x=o[0]+p[1]*math.cos(br); y=o[1]+p[1]*math.sin(br)
            mp[(int(round((X+x*c-y*s)/G)),int(round((Y+x*s+y*c)/G)))]=t
            if mode=='scan':
                spts[(round(x*2)/2.0,round(y*2)/2.0)]=1
    if t-lastprune>2:
        lastprune=t
        for k in [k for k,ts in mp.items() if t-ts>40 and ts<1e8]:
            del mp[k]
    phi=obs['hitch_deg']
    if mode=='scan' or mode=='stop':
        if mode=='stop':
            if abs(v)<0.01: mode='scan'; slt=t
            return (0.0,0.0,sseq[0])
        h=obs['head']
        if not (h.get('settled') and abs(h['gaze_deg']-sseq[sli])<2):
            slt=t
        elif t-slt>0.7:
            sli+=1; slt=t
        if sli>=len(sseq):
            mode='end'
            print('SCAN phi %.1f pts:'%phi+' '.join('%g,%g'%k for k in sorted(spts.keys())))
            print('rig',obs['rig']['trailer_rear'],'tgt',obs.get('target'))
            wake('scan done')
            return (0.0,0.0,0)
        return (0.0,0.0,sseq[sli])
    if mode=='end' or mode=='halt':
        return (0.0,0.0,0)
    look=seq[li]
    if t-look_t>1.0:
        li=(li+1)%len(seq); look_t=t; look=seq[li]
    rig=obs['rig']
    hx,hy=rig['hitch']
    hwx=X+hx*c-hy*s; hwy=Y+hx*s+hy*c
    B=TH+math.radians(rig['trailer_heading_deg'])+math.pi
    ax=hwx+L2*math.cos(B); ay=hwy+L2*math.sin(B)
    bi=idx; bd=1e9
    for j in range(max(0,idx-4),min(len(P),idx+40)):
        dd=(P[j][0]-ax)**2+(P[j][1]-ay)**2
        if dd<bd: bd=dd; bi=j
    idx=bi
    if idx>=len(P)-1 or (ay>11.5 and ax<-9):
        mode='stop'
        print('segment done t%.0f axle(%.1f,%.1f) B%.0f phi%.0f'%(t,ax,ay,math.degrees(B),phi))
        return (0.0,0.0,sseq[0])
    Ld=5.0
    ti=min(len(P)-1,idx+int(Ld/0.25))
    tx,ty=P[ti]
    e=wrap(math.atan2(ty-ay,tx-ax)-B)
    phi_des=-math.degrees(math.atan((L2+H)*2*math.sin(e)/Ld))
    vf=rig.get('vehicle_front',3.2); vhw=rig.get('vehicle_half_width',1.15)
    thw=rig.get('trailer_half_width',1.2)
    rr=rig['trailer_rear']
    rwx=X+rr[0]*c-rr[1]*s; rwy=Y+rr[0]*s+rr[1]*c
    ux=-math.cos(B); uy=-math.sin(B)
    cfr=9.0; cfl=9.0; ctr=9.0; ctl=9.0; tfr=9.0; tfl=9.0; vr=9.0
    for k in mp:
        wx=k[0]*G; wy=k[1]*G
        qx=wx-X; qy=wy-Y
        if qx*qx+qy*qy>200: continue
        lx=qx*c+qy*s; ly=-qx*s+qy*c
        dx=max(lx-vf,(vf-3.9)-lx,0); dy=max(abs(ly)-vhw,0)
        dv=math.hypot(dx,dy)
        if lx>0.5:
            if ly<0: cfr=min(cfr,dv)
            else: cfl=min(cfl,dv)
        else: vr=min(vr,dv)
        px=wx-rwx; py=wy-rwy
        tx2=px*ux+py*uy; ty2=-px*uy+py*ux
        dx=max(tx2-4.6,-tx2,0); dy=max(abs(ty2)-thw,0)
        dt=math.hypot(dx,dy)
        if tx2<2.3:
            if ty2<0: ctr=min(ctr,dt)
            else: ctl=min(ctl,dt)
        else:
            if ty2<0: tfr=min(tfr,dt)
            else: tfl=min(tfl,dt)
    cmin=min(cfr,cfl,ctr,ctl,tfr,tfl,vr)
    if ctr<0.6: phi_des+=15*(0.6-ctr)/0.6
    if ctl<0.6: phi_des-=15*(0.6-ctl)/0.6
    phi_des=clip(phi_des,-30,30)
    if tfr<0.7: phi_des=min(phi_des,phi-25*(0.7-tfr)/0.7)
    if tfl<0.7: phi_des=max(phi_des,phi+25*(0.7-tfl)/0.7)
    if abs(phi)>42:
        mode='halt'; wake('hitch %.0f too big'%phi)
        return (0.0,0.0,look)
    pr=math.radians(phi)
    ff=math.degrees(math.atan(L*math.sin(pr)/(L2+H*math.cos(pr))))
    err=phi-phi_des
    steer=ff+1.8*err
    if cfr<0.7: steer-=30*(0.7-cfr)/0.7
    if cfl<0.7: steer+=30*(0.7-cfl)/0.7
    steer=clip(steer,-38,38)
    spd=-0.7
    if abs(err)>12: spd=-0.5
    if cmin<0.5: spd=-0.35
    if cmin<0.03:
        spd=0.0
        if not woken:
            woken=True
            wake('tight: fr %.2f fl %.2f tr %.2f tl %.2f tfr %.2f tfl %.2f vr %.2f'%(cfr,cfl,ctr,ctl,tfr,tfl,vr))
    if t-lastp>2:
        lastp=t
        print('t%.0f i%d ax(%.1f,%.1f) B%.0f e%.0f phi%.0f des%.0f st%.0f fr%.2f fl%.2f tr%.2f tl%.2f tfr%.2f tfl%.2f vr%.2f'%(t,idx,ax,ay,math.degrees(B),math.degrees(e),phi,phi_des,steer,cfr,cfl,ctr,ctl,tfr,tfl,vr))
    return (steer,spd,look)

