    t=obs['t'];v=obs['motion']['v_mps']
    st=math.radians(obs['steer_deg'])
    if last_t is not None:
        d=t-last_t
        if 0<d<1:
            X+=v*math.cos(TH)*d;Y+=v*math.sin(TH)*d;TH+=v*math.tan(st)/L*d;dist+=abs(v)*d
    last_t=t
    phi=obs['hitch_deg']
    rig=obs['rig'];vf=rig.get('vehicle_front',3.2);vhw=rig.get('vehicle_half_width',1.15)
    views=obs.get('views') or {}
    if mode in ('a1','a2','a3'):
        mind=9.0;fa=9.0
        for name,vw in views.items():
            if not vw or 'mirror' in name: continue
            o=vw.get('origin',[0,0])
            for p in vw.get('walls',[]) or []:
                br=math.radians(p[0]);x=o[0]+p[1]*math.cos(br);y=o[1]+p[1]*math.sin(br)
