import math
L=2.5;H=1.3;L2=3.6;G=0.3
X=0.0;Y=0.0;TH=0.0
last_t=None
mp={}
mode='scan'
t0=None
fz=None
scanseq=[150,64,-64,-150]
seq=[150,64,-64,-150,-64,64]
li=0;look_t=0.0
alpha_f=0.0
lastp=-9.0;lastprune=0.0
woken=False
ncall=0
clr=(9,9,9,9,9,9)

def clip(a,lo,hi):
    return max(lo,min(hi,a))

def control(obs):
    global X,Y,TH,last_t,mode,t0,fz,li,look_t,alpha_f,lastp,lastprune,woken,ncall,clr
    t=obs['t'];v=obs['motion']['v_mps']
    st=math.radians(obs['steer_deg'])
    if last_t is not None:
        d=t-last_t
        if 0<d<1:
            X+=v*math.cos(TH)*d;Y+=v*math.sin(TH)*d;TH+=v*math.tan(st)/L*d
    last_t=t
    c=math.cos(TH);s=math.sin(TH)
    for name,vw in (obs.get('views') or {}).items():
        if not vw:continue
        o=vw.get('origin',[0,0])
        for p in vw.get('walls',[]) or []:
            if p[1]>11:continue
            br=math.radians(p[0])
            x=o[0]+p[1]*math.cos(br);y=o[1]+p[1]*math.sin(br)
            mp[(int(round((X+x*c-y*s)/G)),int(round((Y+x*s+y*c)/G)))]=t
    if t-lastprune>2:
        lastprune=t
        for k in [k for k,ts in mp.items() if t-ts>25]:
            del mp[k]
    phi=obs['hitch_deg']
    rig=obs['rig']
    vf=rig.get('vehicle_front',3.0);vhw=rig.get('vehicle_half_width',1.15);thw=rig.get('trailer_half_width',1.2)
    rr=rig['trailer_rear'];tht=math.radians(rig['trailer_heading_deg'])
    F=TH+tht
    fx_=math.cos(F);fy_=math.sin(F)
    rwx=X+rr[0]*c-rr[1]*s;rwy=Y+rr[0]*s+rr[1]*c
    ncall+=1
    if ncall%3==1:
        cfr=9.0;cfl=9.0;trl=9.0;trr=9.0;tfl=9.0;tfr=9.0
        pts=[]
        for k in mp:
            wx=k[0]*G;wy=k[1]*G
            qx=wx-X;qy=wy-Y
            if qx*qx+qy*qy>300:continue
            lx=qx*c+qy*s;ly=-qx*s+qy*c
            if lx>0.5:
                dx=max(lx-vf,0);dy=max(abs(ly)-vhw,0)
                dv=math.hypot(dx,dy)
                if ly<0:cfr=min(cfr,dv)
                else:cfl=min(cfl,dv)
            px=wx-rwx;py=wy-rwy
            al=px*fx_+py*fy_;lat=-px*fy_+py*fx_
            dx=max(al-4.6,-al,0);dy=max(abs(lat)-thw,0)
            dt=math.hypot(dx,dy)
            if al<2.3:
                if lat>0:trl=min(trl,dt)
                else:trr=min(trr,dt)
            else:
                if lat>0:tfl=min(tfl,dt)
                else:tfr=min(tfr,dt)
            if px*px+py*py<150:pts.append((px,py))
        clr=(cfr,cfl,trl,trr,tfl,tfr)
        if mode=='rev':
            B=F+math.pi
            angs=list(range(-60,61,5));ds=[]
            W=thw+0.25
            for a in angs:
                an=B+math.radians(a);ca=math.cos(an);sa=math.sin(an)
                dm=10.0
                for px,py in pts:
                    sl=px*ca+py*sa
                    if sl<0.2 or sl>=dm:continue
                    if abs(-px*sa+py*ca)<W:dm=sl
                ds.append(dm)
            mx=max(ds);thr=0.85*mx
            blocks=[];cur=[]
            for i,a in enumerate(angs):
                if ds[i]>=thr:cur.append(a)
                else:
                    if cur:blocks.append(cur);cur=[]
            if cur:blocks.append(cur)
            best=0.0;bs=-1e9
            for bl in blocks:
                mid=(bl[0]+bl[-1])/2.0
