    cfr,cfl,trl,trr,tfl,tfr=clr
    cmin=min(clr)
    look=seq[li]
    if t-look_t>1.0:
        li=(li+1)%len(seq);look_t=t;look=seq[li]
    if mode=='scan':
        if t0 is None:t0=t
        k=int((t-t0)/0.6)
        if k>=len(scanseq):
            if cmin<0.12:mode='fwd';fz=None;print('tight start',['%.2f'%q for q in clr])
