    if mode=='fwd':
        if fz is None:fz=(X,Y)
        if math.hypot(X-fz[0],Y-fz[1])>1.5 and abs(phi)<15:
            mode='rev'
        else:
            fs=0.0
            if cfl<0.3:fs=-10.0
            if cfr<0.3:fs=10.0
            return (fs,0.7,look)
    if mode=='halt':
        return (0.0,0.0,look)
    if abs(phi)>35:
        mode='fwd';fz=None;print('t%.0f hitch big -> fwd'%t)
        return (0.0,0.0,look)
    pd=clip(-1.0*alpha_f,-20,20)
    m=0.6
    if trl<m:pd-=20*(m-trl)/m
    if trr<m:pd+=20*(m-trr)/m
    if tfl<m:pd+=15*(m-tfl)/m
    if tfr<m:pd-=15*(m-tfr)/m
