import math
S={'mode':'rev','n':0}
def cl(x,a,b):
    return max(a,min(b,x))
def control(obs):
    S['n']+=1
    h=obs['hitch_deg']
    rig=obs['rig']
    R=rig['trailer_rear']
    th=math.radians(rig['trailer_heading_deg']+180.0)
    ux,uy=math.cos(th),math.sin(th)
    def tf(px,py):
        dx,dy=px-R[0],py-R[1]
        return dx*ux+dy*uy, ux*dy-uy*dx
    P=[]
    for v in (obs.get('views') or {}).values():
        try:
            ox,oy=v['origin']
            for b,d in v.get('walls',[]):
                br=math.radians(b)
                P.append(tf(ox+d*math.cos(br),oy+d*math.sin(br)))
        except Exception:
            pass
    rem=obs['progress']['remaining']
    if S['mode']=='fwd':
        if abs(h)<6:
            S['mode']='rev'
        else:
            return (0.0,0.8,-160)
    if abs(h)>35:
        S['mode']='fwd'
        return (0.0,0.8,-160)
    def free(a):
        ar=math.radians(a); c,s=math.cos(ar),math.sin(ar)
        f=6.0
        for al,lat in P:
            aa=al*c+lat*s; pp=-al*s+lat*c
            if aa>0 and abs(pp)<0.65:
                f=min(f,aa)
        return f
    alpha=None; src=''
    tg=obs.get('target') or {}
    if tg.get('in_sight') and tg.get('dist_m') is not None and tg.get('bearing_deg') is not None:
        e=rig['eye']; br=math.radians(tg['bearing_deg']); d=tg['dist_m']
        al,lat=tf(e[0]+d*math.cos(br),e[1]+d*math.sin(br))
        if al>0:
