import math
S={'X':0.0,'Y':0.0,'p':0.0,'mode':'fwd0','fd':0.0,'idx':0,'n':0,'woke':0}
W=[(0.6,0.0),(-0.6,-0.2),(-1.4,-1.0),(-2.0,-2.3),(-2.3,-3.8),(-2.55,-5.3),(-2.7,-6.4),(-2.7,-9.5)]
def cl(x,a,b):
    return max(a,min(b,x))
def wrap(a):
    while a>math.pi: a-=2*math.pi
    while a<-math.pi: a+=2*math.pi
    return a
def control(obs):
    S['n']+=1
    dt=obs.get('dt',0.1) or 0.1
    v=obs['motion']['v_mps']; d=math.radians(obs['steer_deg'])
    p=S['p']
    S['X']+=v*math.cos(p)*dt; S['Y']+=v*math.sin(p)*dt
    S['p']=p+v/1.25*math.tan(d)*dt
    p=S['p']
    h=obs['hitch_deg']; rig=obs['rig']; R=rig['trailer_rear']
    tx=S['X']+R[0]*math.cos(p)-R[1]*math.sin(p)
    ty=S['Y']+R[0]*math.sin(p)+R[1]*math.cos(p)
    phi=p+math.radians(rig['trailer_heading_deg'])+math.pi
    rem=obs['progress']['remaining']
    look=-150
    if S['mode']=='fwd0':
        if v>0: S['fd']+=v*dt
        if S['fd']<1.8:
            return (0.0,0.8,0)
        S['mode']='rev'
    if S['mode']=='fix':
        if abs(h)<10:
            S['mode']='rev'
        else:
            return (0.0,0.7,look)
    if abs(h)>40:
        S['mode']='fix'
        if S['woke']<3:
            S['woke']+=1
            try: wake('hitch fold %.0f, pulling fwd; trailer at %.2f,%.2f'%(h,tx,ty))
            except Exception: pass
        return (0.0,0.7,look)
    best=None
    for i in range(S['idx'],min(S['idx']+3,len(W)-1)):
        ax,ay=W[i]; bx,by=W[i+1]
        sx,sy=bx-ax,by-ay; L2=sx*sx+sy*sy
        u=cl(((tx-ax)*sx+(ty-ay)*sy)/L2,0,1)
        qx,qy=ax+u*sx,ay+u*sy
        dd=math.hypot(tx-qx,ty-qy)
        if best is None or dd<best[0]: best=(dd,i,u)
    _,i,u=best
    S['idx']=i
    la=1.3
    ax,ay=W[i]; bx,by=W[i+1]
    segl=math.hypot(bx-ax,by-ay)
    rest=segl*(1-u)
    j=i
    px,py=ax+u*(bx-ax),ay+u*(by-ay)
    while la>rest and j+1<len(W)-1:
        la-=rest; j+=1
        ax,ay=W[j]; bx,by=W[j+1]; segl=math.hypot(bx-ax,by-ay); rest=segl; px,py=ax,ay
    f=min(1.0,la/segl) if segl>0 else 0
    lx=px+(bx-px)*f if j!=i else ax+u*(bx-ax)+(bx-ax)/segl*min(la,rest)
    ly=py+(by-py)*f if j!=i else ay+u*(by-ay)+(by-ay)/segl*min(la,rest)
    err=wrap(math.atan2(ly-ty,lx-tx)-phi)
    lim=30 if rem>1.2 else 10
    hd=cl(-1.0*math.degrees(err),-lim,lim)
    st=cl(3.0*(h-hd),-45,45)
    sp=-0.4 if rem>1.5 else -0.3
    if S['n']%15==0:
        print('t%.1f rem%.1f T(%.2f,%.2f) phi%.0f h%.1f hd%.1f i%d'%(obs['t'],rem,tx,ty,math.degrees(phi),h,hd,i))
    return (st,sp,look)

